if(!globalThis.__JIOFLOW_TEST__){window.addEventListener('storage',event=>{if(event.key==='jioflow.auth.v1'){try{authDirectory=JSON.parse(event.newValue)||{accounts:[],stores:[]}}catch{}return;}if(event.key==='jioflow.demo.v1'||event.key==='jioflow.store.'+activeStoreId){try{db=JSON.parse(event.newValue);render()}catch{}}});$('#modal').addEventListener('cancel',()=>{if(pendingConfirmation){const resolve=pendingConfirmation;pendingConfirmation=null;resolve(false)}});restoreDemoSession();const allowed=['dashboard','customers','orders','new','import','products','courier','reports','profit','agentreports','agentdetail','team','admins','creator','owners','platformadmins','platformagents','platformsettings','platformdetail','access','settings','permanent','profile','stores'];const initial=location.hash.slice(1);if(allowed.includes(initial))page=initial;window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(allowed.includes(p)&&p!==page){page=p;render()}});render();}
